 foreach(json_decode(file_get_contents($dir.'/bodies'),true) as $body){$client=stream_socket_accept($server,15);gateCheck(is_resource($client),'Missing loopback GET');$head='';while(($line=fgets($client))!==false){$head.=$line;if(trim($line)==='')break;}gateCheck(str_starts_with($head,"GET /api/v1/tasks/owned "),'Fixture attempted non-owned task or submission');file_put_contents($dir.'/calls','GET\n',FILE_APPEND);fwrite($client,"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: ".strlen($body)."\r\nConnection: close\r\n\r\n".$body);fclose($client);}fclose($server);exit(0);
