  $row=['request_id'=>$rid,'tenant_id'=>1,'user_id'=>1,'key_id'=>0,'kind'=>'market','method'=>'POST','path'=>'/api/v1/tasks','status'=>'running','billing_status'=>'reserved','active'=>1,'upstream_task_id'=>'owned','consumption_ids'=>'[]','snapshot'=>S::encode($snapshot),'payload_hash'=>hash('sha256',$rid),'response_blob'=>'','budget_user'=>5,'budget_tenant'=>1]+S::timestamp();$row['id']=S::table('request')->insertGetId($row);C::enter($rid);B::reserve($row,['user'=>5,'tenant'=>1,'snapshot'=>$snapshot]);C::leave();$reserved=$wallets();$originalBooked=(float)S::table('request')->where('id',$row['id'])->value('actual_user');$execute=new ReflectionMethod(G::class,'execute');
  for($i=0;$i<4;$i++){$id='req_gate_query_'.bin2hex(random_bytes(12));$q=['request_id'=>$id,'tenant_id'=>1,'user_id'=>1,'key_id'=>0,'kind'=>'market','method'=>'GET','path'=>'/api/v1/tasks/owned','status'=>'accepted','billing_status'=>'none','active'=>1,'consumption_ids'=>'[]','snapshot'=>'{}','payload_hash'=>hash('sha256',$id),'response_blob'=>'','budget_user'=>0,'budget_tenant'=>0]+S::timestamp();$q['id']=S::table('request')->insertGetId($q);$query=array_replace($contract,['kind'=>'market','role'=>'query','history'=>true,'executor'=>'json','billable'=>false,'params'=>['task_id'=>'owned']]);$response=$execute->invoke(null,request(),$q,$query,[],['user'=>0,'tenant'=>0,'snapshot'=>[]],false);$owner=S::table('request')->where('id',$row['id'])->find();
